import "./DXButton.scss";
import Button from 'react-bootstrap/Button';
import React, { FormEventHandler, MouseEventHandler, MutableRefObject } from "react";
import { ExtendableProps, pickDomProps } from "../../utilities/extendable";

export type DisplayType = "primary" | "secondary" | "unstyled" | undefined;
export type ButtonType = "button" | "submit" | "reset" | undefined;

export interface ButtonProps {
    label: string;
    hideLabel?: boolean;
    id?: string;
    role?: string;
    ariaExpanded?: boolean;
    type?: ButtonType;
    hidden?: boolean;
    disabled?: boolean;
    className?: string;
    value?: string | number;
    style?: {};
    reactRef?: MutableRefObject<any>;
    onClick?: Function | FormEventHandler | MouseEventHandler<HTMLButtonElement>;
    displayType?: DisplayType;
    icon?: {
        class: string;
        position?: "left" | "right";
        testId?: string;
    };
    tabIndex?: number;
}

export interface HelperAttrs {
    "data-testid"?: string;
}

/**
 * Extra props (data-*, aria-*, handlers, ...) and `ref` go to the root button. `reactRef` is kept for compatibility;
 * when both are given, `ref` wins.
 */
const DXButton = ( props: ExtendableProps<ButtonProps & HelperAttrs, "button"> ) => {
    // Own props are pulled out so only DOM attributes reach the root.
    const { label, hideLabel, id, role, ariaExpanded, type, hidden, disabled, className, value, style, reactRef, onClick, displayType, icon, tabIndex, "data-testid": dataTestId, ref, ...rest } = props;
    const domProps = pickDomProps( rest );
    const getButtonClass = () => {
        let className = "dxButton";
        if ( props.hideLabel ) {
            className += " dxButton--icon-only";
        }
        // Check for aditional classes passed via prop
        if ( props.className ) {
            className = `${props.className} ${className}`;
        }
        return className;
    };

    const handleEvent = ( e: any ) => {
        if ( props.onClick ) {
            if ( e.type === "click" || ( e.type === "keydown" && e.keyCode === 13 ) || ( e.type === "keydown" && e.keyCode === 32 ) ) {
                e.preventDefault();
                if ( e.target.nodeName === 'DIV' ) e.target = e.target.parentNode;
                props.onClick( e );
            }
        }
        return;
    };

    return (
        <Button {...domProps} className={getButtonClass()}
            variant={props.displayType ? props.displayType : "primary"}
            style={props.style ? { ...props.style } : undefined}
            id={props.id ? props.id : undefined}
            ref={ref ?? ( props.reactRef ? props.reactRef : undefined )}
            role={props.role ? props.role : "button"}
            aria-label={props.hideLabel ? props.label : domProps["aria-label"] as string | undefined}
            aria-expanded={props.ariaExpanded ? props.ariaExpanded : domProps["aria-expanded"] as React.AriaAttributes["aria-expanded"]}
            type={props.type ? props.type : "button"}
            hidden={props.hidden ? props.hidden : undefined}
            value={props.value ? props.value : undefined}
            disabled={props.disabled ? props.disabled : undefined}
            onClick={( e ) => handleEvent( e )}
            onKeyDown={( e ) => {
                // The consumer's handler runs first and can stop the component's own keyboard handling
                ( domProps.onKeyDown as React.KeyboardEventHandler<HTMLButtonElement> | undefined )?.( e );
                if ( !e.defaultPrevented ) handleEvent( e );
            }}
            tabIndex={props.tabIndex}
            data-testid={props["data-testid"] ? props["data-testid"] : undefined}>
            {props.icon && props.icon.class && props.icon.position != "right" &&
                <i className={props.icon.class} data-testid={props.icon.testId ? props.icon.testId : ""} ></i>
            }
            {!props.hideLabel &&
                <div className="dxButton__label">{props.label}</div>
            }
            {props.icon && props.icon.class && props.icon.position === "right" &&
                <i className={props.icon.class} data-testid={props.icon.testId ? props.icon.testId : ""} ></i>
            }
        </Button>
    );
};

export default DXButton;
